        'title' => 'By Grace I\'m Saved',
        'first_line' => 'By grace I\'m savedgrace free and boundless! My heart, believ\'st thou this or not?',
        'writer' => 'Christian Ludwig Scheidt · tr. Matthias Loy',
        'attribution' => '',
        'year' => 1742,
        'key' => 'F',
        'time' => '4/4',
        'bpm' => 120,
        'metre' => '9.8.9.8.8.8',
        'themes' => ['Assurance', 'Cross'],
        'collections' => ['hymns', 'cross', 'faith'],
        'scripture' => ['Eph 2:4-9'],
        'rights' => [
            'text' => [
                'license' => 'PD',
                'basis' => 'published 1742',
                'source' => 'open-hymnal',
            ],
            'tune' => [
                'license' => 'PD',
